insert into public.exercises
  (name, target_muscle, equipment, difficulty, default_sets, default_reps, default_rest_sec, instructions)
values
  ('Push-up', 'chest', 'none', 'beginner', 3, '8-12', 60, 'Hands a little wider than shoulders. Keep body in one straight line, lower chest near the floor, push back up.'),
  ('Knee push-up', 'chest', 'none', 'beginner', 3, '10-15', 60, 'Same as a push-up but with knees on the floor. Keep hips in line with shoulders.'),
  ('Dumbbell bench press', 'chest', 'dumbbells, flat bench', 'beginner', 3, '8-12', 75, 'Lie on the bench, dumbbells over chest. Lower slowly to chest level, then press up without locking elbows hard.'),
  ('Barbell bench press', 'chest', 'barbell, flat bench', 'intermediate', 4, '6-10', 90, 'Feet flat, shoulder blades squeezed. Lower bar to mid-chest with control, press up. Use a spotter for heavy sets.'),
  ('Incline dumbbell press', 'chest', 'dumbbells, incline bench', 'intermediate', 3, '8-12', 75, 'Bench at a low incline. Press dumbbells up over upper chest, lower slowly to the sides of the chest.'),
  ('Dumbbell fly', 'chest', 'dumbbells, flat bench', 'intermediate', 3, '10-12', 60, 'Arms slightly bent, open them wide in an arc until you feel a chest stretch, then bring them back together.'),
  ('Machine chest press', 'chest', 'chest press machine', 'beginner', 3, '10-12', 60, 'Set the seat so handles are at chest height. Push forward, return slowly without letting the weight stack touch.'),
