  ('Treadmill brisk walk', 'cardio', 'treadmill', 'beginner', 1, '20 min', 0, 'Walk at a pace where you can talk but not sing. A small incline makes it harder.'),
  ('Stationary cycling', 'cardio', 'exercise bike', 'beginner', 1, '15-20 min', 0, 'Adjust seat so the knee is slightly bent at the bottom. Keep a steady, comfortable pace.'),
  ('Elliptical trainer', 'cardio', 'elliptical machine', 'beginner', 1, '15-20 min', 0, 'Stand tall, use arms and legs together at a steady pace.'),
